window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"thymus":{"title":"Thymus","short":"Lymfoïd orgaan achter het borstbeen waar T-lymfocyten uitrijpen en geselecteerd worden.","definition":"<p>De <b>thymus</b> (zwezerik) ligt achter het borstbeen. Hier rijpen T-lymfocyten uit en worden ze getest op nut en veiligheid (positieve en negatieve selectie).</p><p>De thymus is het actiefst in de jeugd en neemt daarna geleidelijk af.</p>","image_url":"","wiki_title":"Thymus","match":"thymus"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"crusta":{"title":"Crusta","short":"Korstje van ingedroogd wondvocht, bloed of pus op het huidoppervlak.","definition":"<p>Een <b>crusta</b> (korst) is opgedroogd exsudaat — wondvocht, bloed of pus — op de huid.</p><p>Het is een secundaire efflorescentie die ontstaat nadat een blaasje of wondje is opengegaan.</p>","image_url":"","wiki_title":"Crust (dermatology)","match":"crusta|crustae|korst"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"herpes zoster":{"title":"Herpes zoster (gordelroos)","short":"Herpes zoster is de reactivatie van het varicella-zostervirus uit een sensibel ganglion, met pijnlijke blaasjes in één dermatoom.","definition":"<p>Na waterpokken blijft het <strong>varicella-zostervirus</strong> latent aanwezig in sensibele ganglia (spinale ganglia of hersenzenuwganglia). Bij afnemende cellulaire afweer (ouderdom, immuunsuppressie) kan het reactiveren.</p><p>Dan ontstaan pijnlijke, gegroepeerde blaasjes op een rode ondergrond in één <em>dermatoom</em>, meestal eenzijdig. Complicaties zijn postherpetische neuralgie en, bij de n. ophthalmicus, oogbetrokkenheid (zoster ophthalmicus).</p>","image_url":"","wiki_title":"Shingles","match":"herpes zoster|gordelroos|zoster","option_only":true},"bovenste luchtweginfectie":{"title":"Bovenste luchtweginfectie","short":"Een bovenste luchtweginfectie is een (meestal virale) infectie van neus, keel, bijholten of strottenhoofd, zoals een verkoudheid.","definition":"<p>Een <strong>bovenste luchtweginfectie</strong> betreft de luchtwegen boven de stembanden: neus, bijholten, farynx en larynx. Voorbeelden zijn de gewone verkoudheid (rhinitis), faryngitis, sinusitis en laryngitis.</p><p>Ze worden meestal veroorzaakt door virussen (rhino-, adeno-, coronavirussen) en zijn zelflimiterend. Antibiotica zijn zelden nodig.</p>","image_url":"","wiki_title":"Upper respiratory tract infection","match":"bovenste luchtweginfectie|bovensteluchtweginfectie|blwi","option_only":true},"amoxicilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxicilline|amoxicillin","option_only":true},"doxycycline":{"title":"Doxycycline","short":"Doxycycline is een tetracycline: een bacteriostatisch antibioticum dat de eiwitsynthese remt via het 30S-ribosoom.","definition":"<p><strong>Doxycycline</strong> behoort tot de <em>tetracyclines</em>. Het bindt aan de 30S-subeenheid van het bacteriële ribosoom en remt zo de eiwitsynthese (bacteriostatisch).</p><p>Het is werkzaam tegen veel luchtwegpathogenen en tegen intracellulaire verwekkers zoals <em>Chlamydia</em>, <em>Mycoplasma</em>, <em>Rickettsia</em> en <em>Borrelia</em> (ziekte van Lyme). Niet geven aan zwangeren en jonge kinderen (verkleuring van tanden en botten); kan fotosensibiliteit geven.</p>","image_url":"","wiki_title":"Doxycycline","match":"doxycycline","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"psoriasis vulgaris":{"title":"Psoriasis vulgaris","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers, vaak op ellebogen, knieën en hoofdhuid.","definition":"<p>Bij <strong>psoriasis vulgaris</strong> stimuleert een T-cel-gemedieerde ontsteking (o.a. de IL-23/Th17-as) een sterk versnelde deling en onvolledige verhoorning van keratinocyten.</p><p>Dat geeft scherp begrensde, erythemateuze plaques met <em>zilverwitte schilfering</em>, typisch op de strekzijden (ellebogen, knieën), de hoofdhuid en de bilnaad. Kenmerkend zijn het köbnerfenomeen en nagelafwijkingen (putjes, olievlekken). Een deel van de patiënten ontwikkelt artritis psoriatica.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis vulgaris|psoriasis","option_only":true},"stembandpoliep":{"title":"Stembandpoliep","short":"Een stembandpoliep is een goedaardige, meestal eenzijdige zwelling op de stemband, vaak door stemmisbruik of roken; het geeft heesheid.","definition":"<p>Een <strong>stembandpoliep</strong> is een goedaardige, vaak eenzijdige uitgroei van de stemband, meestal aan de vrije rand. Ze ontstaat door overbelasting van de stem (schreeuwen), roken of irritatie (reflux); soms na een bloedinkje in de stemband.</p><p>De belangrijkste klacht is <em>heesheid</em> en een minder belastbare stem. Diagnose door laryngoscopie; behandeling is meestal microchirurgische verwijdering en stemtherapie.</p>","image_url":"","wiki_title":"Vocal fold polyp","match":"stembandpoliep|stembandpoliepen","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"nervus vagus":{"title":"N. vagus (X)","short":"De n. vagus (X) is de belangrijkste parasympathische zenuw; hij innerveert hart, longen en het maag-darmkanaal tot het distale colon transversum.","definition":"<p>De <strong>n. vagus</strong> verlaat de schedel via het foramen jugulare en loopt in de halsvaatschede omlaag. Hij levert parasympathische vezels aan hart (vertraging), luchtwegen en darm, motorische vezels aan farynx en larynx (o.a. via de n. laryngeus recurrens) en sensibele informatie uit de inwendige organen, zoals van baroreceptoren in de aortaboog.</p>","image_url":"","wiki_title":"Vagus nerve","match":"nervus vagus|n. vagus|vagus|hersenzenuw x","option_only":true},"n. facialis":{"title":"N. facialis (VII)","short":"De n. facialis (VII) innerveert de mimische spieren en verzorgt ook smaak (voorste 2/3 tong), traan- en speekselsecretie.","definition":"<p>De <strong>n. facialis</strong> treedt uit bij de brughoek, loopt door het os temporale (canalis facialis) en verlaat de schedel via het foramen stylomastoideum; daarna splitst hij zich in de glandula parotidea in vijf takken. Naast de mimische spieren innerveert hij de m. stapedius. Bij een perifere facialisparese is de hele gezichtshelft verlamd, inclusief het voorhoofd.</p>","image_url":"","wiki_title":"Facial nerve","match":"n. facialis|nervus facialis|hersenzenuw vii|aangezichtszenuw","option_only":true},"cva":{"title":"CVA (beroerte)","short":"Een CVA (beroerte) is plotselinge neurologische uitval door een herseninfarct of hersenbloeding.","definition":"<p>Een <strong>cerebrovasculair accident</strong> is in ongeveer 80% van de gevallen een herseninfarct en in de rest een hersenbloeding (intracerebraal of subarachnoïdaal). Beeldvorming (CT) is nodig om bloeding en infarct te onderscheiden, omdat de behandeling sterk verschilt. Belangrijke risicofactoren zijn hypertensie, roken, diabetes, hypercholesterolemie en boezemfibrilleren.</p>","image_url":"","wiki_title":"Stroke","match":"cva|beroerte|cerebrovasculair accident|stroke","option_only":true},"neuroborreliose":{"title":"Neuroborreliose","short":"Neuroborreliose is een uiting van de ziekte van Lyme in het zenuwstelsel, met o.a. radiculitis, facialisparese en meningitis.","definition":"<p>Bij <strong>neuroborreliose</strong> verspreidt <em>Borrelia burgdorferi</em> zich naar het zenuwstelsel, weken tot maanden na een tekenbeet. Typisch zijn hevige, ’s nachts verergerende radiculaire pijn (meningoradiculitis, syndroom van Bannwarth), een (soms dubbelzijdige) perifere facialisparese en lymfocytaire meningitis. Diagnose via liquoronderzoek; behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Lyme neuroborreliosis","match":"neuroborreliose|lyme-neuroborreliose","option_only":true},"sinusitis":{"title":"Sinusitis (bijholteontsteking)","short":"Sinusitis is een ontsteking van het slijmvlies van neus en bijholten, met verstopte neus, pijn in het gezicht en afscheiding.","definition":"<p>Acute <strong>rhinosinusitis</strong> ontstaat meestal na een virale verkoudheid; soms volgt een bacteriële infectie (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Klachten zijn een verstopte neus, (purulente) afscheiding, pijn of drukgevoel boven de bijholten en verminderde reuk. Meestal herstelt het binnen enkele weken zonder antibiotica. Chronische sinusitis duurt langer dan 12 weken.</p>","image_url":"","wiki_title":"Sinusitis","match":"sinusitis|bijholteontsteking|rhinosinusitis","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"trombopenie":{"title":"Trombocytopenie","short":"Trombocytopenie is een te laag aantal bloedplaatjes, met een verhoogde neiging tot bloedingen.","definition":"<p>Bij <strong>trombocytopenie</strong> (&lt;150 × 10⁹/L) ontstaan pas bij lage waarden (&lt;20–50) spontane huid- en slijmvliesbloedingen zoals petechiën en neusbloedingen. Oorzaken: verminderde aanmaak (beenmergziekte, chemotherapie, B12-tekort), versterkte afbraak (ITP, HIT, DIS, TTP), sequestratie in een vergrote milt of verdunning. Een pseudotrombopenie door klontering in EDTA-buizen moet worden uitgesloten.</p>","image_url":"","wiki_title":"Thrombocytopenia","match":"trombopenie|trombocytopenie","option_only":true},"psoriasis":{"title":"Psoriasis","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers.","definition":"<p>Bij <strong>psoriasis</strong> stimuleert een T-celreactie (IL-23/Th17) een sterk versnelde deling van keratinocyten. Er ontstaan schilferende plaques op strekzijden, hoofdhuid en bilnaad, met nagelafwijkingen en het köbnerfenomeen. Een deel van de patiënten krijgt artritis psoriatica. Behandeling met lokale middelen, lichttherapie of systemische en biologische middelen.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis","option_only":true},"polycysteus ovariumsyndroom":{"title":"Polycysteus ovariumsyndroom (PCOS)","short":"PCOS is een hormonale stoornis met onregelmatige of uitblijvende ovulatie, verhoogde androgenen en/of veel kleine follikels in de ovaria.","definition":"<p>Volgens de Rotterdam-criteria spreekt men van <strong>PCOS</strong> bij twee van drie kenmerken: oligo- of anovulatie, klinische of biochemische hyperandrogenisme (acne, hirsutisme) en polycysteuze ovaria op de echo. Het gaat vaak samen met insulineresistentie en overgewicht. Het is een veelvoorkomende oorzaak van subfertiliteit.</p>","image_url":"","wiki_title":"Polycystic ovary syndrome","match":"polycysteus ovariumsyndroom|pcos|polycysteus ovarium syndroom","option_only":true},"mammacarcinoom":{"title":"Mammacarcinoom (borstkanker)","short":"Het mammacarcinoom is een kwaadaardige tumor van de borstklier, de meest voorkomende kanker bij vrouwen.","definition":"<p>Het <strong>mammacarcinoom</strong> is meestal een invasief carcinoom uitgaande van de afvoergangen (ductaal) of lobjes (lobulair). Risicofactoren zijn leeftijd, familiaire belasting (BRCA1/2), lange oestrogeenblootstelling en alcohol. Behandeling hangt af van stadium en receptorstatus (oestrogeen, progesteron, HER2): chirurgie, radiotherapie, hormonale therapie, chemotherapie en doelgerichte therapie. Er is een bevolkingsonderzoek met mammografie.</p>","image_url":"","wiki_title":"Breast cancer","match":"mammacarcinoom|borstkanker","option_only":true},"prostaatcarcinoom":{"title":"Prostaatcarcinoom","short":"Het prostaatcarcinoom is een kwaadaardige tumor van de prostaat, meestal een adenocarcinoom uitgaand van de perifere zone.","definition":"<p><strong>Prostaatkanker</strong> komt vooral voor bij oudere mannen en groeit vaak langzaam. Vroege stadia geven meestal geen klachten; gevorderde stadia kunnen plasklachten en botmetastasen (botpijn) geven. Diagnostiek met rectaal toucher, PSA, MRI en biopten (Gleason-score). Behandeling varieert van actief volgen tot operatie, radiotherapie en hormonale therapie.</p>","image_url":"","wiki_title":"Prostate cancer","match":"prostaatcarcinoom|prostaatkanker","option_only":true},"cervixcarcinoom":{"title":"Cervixcarcinoom","short":"Het cervixcarcinoom is kanker van de baarmoederhals, vrijwel altijd veroorzaakt door een persisterende infectie met hoog-risico-HPV.","definition":"<p>Het <strong>cervixcarcinoom</strong> ontstaat via voorstadia (CIN) in de transformatiezone, meestal als plaveiselcelcarcinoom. Klachten: contactbloedingen (na gemeenschap), intermenstrueel bloedverlies en afscheiding. Preventie via HPV-vaccinatie en het bevolkingsonderzoek (hrHPV-test). Behandeling afhankelijk van stadium: operatie of (chemo)radiatie.</p>","image_url":"","wiki_title":"Cervical cancer","match":"cervixcarcinoom|baarmoederhalskanker","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"stembandknobbeltjes":{"title":"Stembandknobbeltjes","short":"Stembandknobbeltjes zijn kleine, symmetrische verdikkingen op de stembanden door overbelasting van de stem.","definition":"<p><strong>Stembandknobbeltjes</strong> zitten op de vrije rand van beide stembanden, op de overgang van het voorste naar het middelste derde. Ze ontstaan door langdurige stembelasting (schreeuwen, zingen) en geven heesheid en een snel vermoeide stem. Behandeling is in eerste instantie logopedie.</p>","image_url":"","wiki_title":"Vocal fold nodule","match":"stembandknobbeltjes|noduli van de stembanden","option_only":true},"sterilisatie":{"title":"Sterilisatie (infectiepreventie)","short":"Sterilisatie is het doden of verwijderen van alle micro-organismen, inclusief bacteriële sporen.","definition":"<p><strong>Sterilisatie</strong> gebeurt meestal met stoom onder druk (autoclaaf), of met gas, plasma of straling voor hittegevoelige materialen. Het is nodig voor instrumenten die steriel weefsel of de bloedbaan binnengaan. Prionen zijn extra resistent en vragen speciale procedures.</p>","image_url":"","wiki_title":"Sterilization (microbiology)","match":"sterilisatie","option_only":true},"corpus alienum in de luchtweg":{"title":"Corpus alienum in de luchtweg","short":"Een corpus alienum in de luchtweg is een ingeademd vreemd voorwerp; bij jonge kinderen een belangrijke oorzaak van plotselinge benauwdheid.","definition":"<p>Bij <strong>aspiratie van een vreemd voorwerp</strong> (vaak pinda's, speelgoedonderdelen) ontstaan plotseling hoesten, verslikken en benauwdheid; later kan een eenzijdig piepen, verminderd ademgeruis of een recidiverende pneumonie optreden. Het voorwerp komt vaak in de rechter hoofdbronchus terecht. Verwijdering via een bronchoscopie.</p>","image_url":"","wiki_title":"Foreign body aspiration","match":"corpus alienum in de luchtweg|corpus alienum|vreemd voorwerp","option_only":true},"laryngitis subglottica":{"title":"Laryngitis subglottica (pseudokroep)","short":"Pseudokroep is een virale ontsteking onder de stembanden bij jonge kinderen, met blafhoest, heesheid en inspiratoire stridor.","definition":"<p><strong>Pseudokroep</strong> wordt meestal veroorzaakt door para-influenzavirussen en treedt vaak ’s nachts op bij kinderen van 6 maanden tot 3 jaar. Behandeling: geruststellen en bij matig tot ernstige klachten dexamethason; bij ernstige stridor in rust adrenalinevernevelingen. Het moet onderscheiden worden van epiglottitis.</p>","image_url":"","wiki_title":"Croup","match":"laryngitis subglottica|pseudokroep|kroep","option_only":true},"trisomie 21":{"title":"Trisomie 21 (syndroom van Down)","short":"Het syndroom van Down ontstaat door een extra (deel van) chromosoom 21, met verstandelijke beperking en kenmerkende uiterlijke en medische kenmerken.","definition":"<p>Bij <strong>trisomie 21</strong> (meestal door non-disjunctie, risico stijgend met de leeftijd van de moeder) zijn er o.a. hypotonie, een kenmerkend gezicht, één handpalmplooi, hartafwijkingen (AVSD), duodenumatresie, ziekte van Hirschsprung, hypothyreoïdie, een verhoogd risico op leukemie en vroege Alzheimer. Prenatale screening gebeurt met de NIPT.</p>","image_url":"","wiki_title":"Down syndrome","match":"trisomie 21|syndroom van down|down syndroom","option_only":true},"atopische constitutie":{"title":"Atopische constitutie","short":"Atopie is een erfelijke aanleg om IgE te maken tegen alledaagse allergenen, met een verhoogde kans op eczeem, astma en hooikoorts.","definition":"<p>Bij een <strong>atopische constitutie</strong> komen constitutioneel eczeem, voedselallergie, allergisch astma en allergische rhinitis vaak in een volgorde voor (de ‘atopische mars’). De aanleg kan worden aangetoond met specifiek IgE of huidpriktesten.</p>","image_url":"","wiki_title":"Atopy","match":"atopische constitutie|atopie|atopisch","option_only":true},"postnasal drip":{"title":"Postnasal drip","short":"Bij postnasal drip loopt slijm uit neus of bijholten via de achterkant van de keel naar beneden, wat kuchen en hoesten geeft.","definition":"<p><strong>Postnasal drip</strong> (upper airway cough syndrome) is een veelvoorkomende oorzaak van chronische hoest. Het hangt samen met allergische of niet-allergische rhinitis en chronische rhinosinusitis. Patiënten hebben het gevoel steeds te moeten schrapen of slikken.</p>","image_url":"","wiki_title":"Post-nasal drip","match":"postnasal drip|postnasale drip","option_only":true},"juveniel larynxpapilloom":{"title":"Larynxpapillomatose","short":"Larynxpapillomen zijn goedaardige, wratachtige gezwellen in het strottenhoofd door HPV 6 en 11, met heesheid en soms ademnood.","definition":"<p>Bij <strong>recidiverende respiratoire papillomatose</strong> ontstaan papillomen op de stembanden en in de luchtweg, vooral bij jonge kinderen (vermoedelijk besmetting tijdens de geboorte) en bij volwassenen. Klachten: heesheid en bij groei stridor. Ze komen vaak terug na chirurgische verwijdering; HPV-vaccinatie kan het risico verkleinen.</p>","image_url":"","wiki_title":"Recurrent respiratory papillomatosis","match":"juveniel larynxpapilloom|larynxpapilloom|larynxpapillomatose","option_only":true},"otitis media met effusie":{"title":"Otitis media met effusie","short":"Bij otitis media met effusie zit er vocht achter een intact trommelvlies zonder acute ontsteking, met gehoorverlies als belangrijkste klacht.","definition":"<p><strong>Otitis media met effusie</strong> komt vooral bij jonge kinderen voor, vaak na een acute otitis of verkoudheid, door een slecht werkende buis van Eustachius. Het geeft een geleidingsverlies en soms taalachterstand. Meestal verdwijnt het binnen enkele maanden; bij aanhoudend gehoorverlies kunnen trommelvliesbuisjes worden geplaatst.</p>","image_url":"","wiki_title":"Otitis media","match":"otitis media met effusie|lijmoor","option_only":true},"otitis media acuta":{"title":"Otitis media acuta","short":"Otitis media acuta is een acute middenoorontsteking met oorpijn, koorts en een rood, bomberend trommelvlies.","definition":"<p><strong>Acute otitis media</strong> komt vooral bij jonge kinderen voor, vaak na een verkoudheid; verwekkers zijn virussen en bacteriën (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Een loopoor ontstaat bij perforatie van het trommelvlies. Meestal geneest het spontaan; pijnstilling is de basis, antibiotica alleen bij risicofactoren of ernstig beloop.</p>","image_url":"","wiki_title":"Otitis media","match":"otitis media acuta|acute otitis media|middenoorontsteking","option_only":true},"a. sphenopalatina":{"title":"A. sphenopalatina","short":"De a. sphenopalatina is een eindtak van de a. maxillaris die het achterste deel van de neusholte voorziet; bron van achterste neusbloedingen.","definition":"<p>De <strong>a. sphenopalatina</strong> komt via het foramen sphenopalatinum de neusholte in. Ze voorziet het grootste deel van het neusslijmvlies. Bloedingen hieruit (posterieure epistaxis) zijn moeilijker te stelpen dan bloedingen uit de plexus van Kiesselbach vooraan in het septum.</p>","image_url":"","wiki_title":"Sphenopalatine artery","match":"a. sphenopalatina|arteria sphenopalatina","option_only":true},"a. ethmoidalis anterior":{"title":"A. ethmoidalis anterior","short":"De aa. ethmoidales zijn takken van de a. ophthalmica (carotis interna) die het bovenste deel van de neusholte voorzien.","definition":"<p>De <strong>a. ethmoidalis anterior en posterior</strong> lopen vanuit de orbita door de zeefbeencellen naar het bovenste deel van de neusholte en het septum. Ze dragen samen met takken van de a. carotis externa bij aan de plexus van Kiesselbach. Hoge neusbloedingen kunnen uit deze vaten komen.</p>","image_url":"","wiki_title":"Anterior ethmoidal artery","match":"a. ethmoidalis anterior|arteria ethmoidalis anterior|a. ethmoidalis posterior","option_only":true},"nervus maxillaris":{"title":"N. maxillaris (V2)","short":"De n. maxillaris (V2) is de tweede, zuiver sensibele tak van de n. trigeminus, voor de middelste gezichtsetage.","definition":"<p>De <strong>n. maxillaris</strong> verlaat de schedel via het foramen rotundum en verzorgt het gevoel van de wang, het onderste ooglid, de zijkant van de neus, de bovenlip, de boventanden, het gehemelte en het slijmvlies van de bijholten. Een belangrijke eindtak is de n. infraorbitalis.</p>","image_url":"","wiki_title":"Maxillary nerve","match":"nervus maxillaris|n. maxillaris|v2","option_only":true},"ramus auricularis nervi vagi":{"title":"Ramus auricularis van de n. vagus","short":"De ramus auricularis van de n. vagus verzorgt het gevoel van een deel van de uitwendige gehoorgang en de oorschelp.","definition":"<p>Prikkeling van de <strong>ramus auricularis</strong> (zenuw van Arnold), bijvoorbeeld bij het schoonmaken van de gehoorgang, kan via een vagale reflex hoesten (Arnold-reflex) of soms een vasovagale reactie uitlokken. Oorpijn kan ook worden gerefereerd vanuit andere vagusgebieden, zoals de larynx.</p>","image_url":"","wiki_title":"Auricular branch of vagus nerve","match":"ramus auricularis nervi vagi|ramus auricularis van de n. vagus|zenuw van arnold","option_only":true},"coagulopathie":{"title":"Coagulopathie","short":"Een coagulopathie is een stoornis in de bloedstolling, met een verhoogde bloedingsneiging.","definition":"<p>Oorzaken van een <strong>coagulopathie</strong> zijn erfelijke stollingsfactortekorten (hemofilie, von Willebrand), leverziekte (minder aanmaak), vitamine K-tekort of cumarines, diffuse intravasale stolling, verdunning bij massale transfusie en antistollingsmiddelen. PT, APTT, fibrinogeen en plaatjesgetal helpen de oorzaak te vinden.</p>","image_url":"","wiki_title":"Coagulopathy","match":"coagulopathie|stollingsstoornis","option_only":true},"diplopie":{"title":"Diplopie (dubbelzien)","short":"Diplopie is dubbelzien; binoculaire diplopie verdwijnt bij afdekken van één oog en wijst op een stoornis in de oogstand.","definition":"<p>Bij <strong>binoculaire diplopie</strong> kijken de ogen niet in dezelfde richting, door een parese van een hersenzenuw (III, IV, VI), een stoornis van de neuromusculaire overdracht (myasthenie), een probleem in de oogkas (Graves-orbitopathie, fractuur) of een centraal probleem. Monoculaire diplopie (blijft bij afdekken) wijst op een oogprobleem zoals cataract of astigmatisme.</p>","image_url":"","wiki_title":"Diplopia","match":"diplopie|dubbelzien|dubbelbeelden","option_only":true},"acuut reuma (engels: rheumatic fever)":{"title":"Acuut reuma","short":"Acuut reuma is een ontstekingsziekte enkele weken na een keelinfectie met groep A-streptokokken, door kruisreactie van antistoffen.","definition":"<p><strong>Acuut reuma</strong> geeft volgens de Jones-criteria o.a. carditis, een migrerende polyartritis, chorea van Sydenham, erythema marginatum en subcutane noduli. De carditis kan leiden tot chronische reumatische klepziekte, vooral van de mitralisklep. Het is in Nederland zeldzaam geworden, maar wereldwijd nog een belangrijke oorzaak van hartziekte.</p>","image_url":"","wiki_title":"Rheumatic fever","match":"acuut reuma (engels: rheumatic fever)|acuut reuma|rheumatic fever","option_only":true},"gastro-oesophageale reflux":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"gastro-oesophageale reflux","option_only":true},"gastrofaryngeale reflux":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"gastrofaryngeale reflux","option_only":true},"hepatosplenomegalie":{"title":"Hepatosplenomegalie","short":"Hepatosplenomegalie is een gelijktijdige vergroting van lever en milt.","definition":"<p>Oorzaken van <strong>hepatosplenomegalie</strong> zijn o.a. infecties (EBV, CMV, malaria, leishmaniasis), hematologische ziekten (leukemie, lymfoom, myeloproliferatieve ziekten, hemolyse), portale hypertensie, stapelingsziekten (Gaucher) en congestief hartfalen.</p>","image_url":"","wiki_title":"Hepatosplenomegaly","match":"hepatosplenomegalie","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"echo van de lever":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo van de lever","option_only":true},"ovariumcarcinoom":{"title":"Ovariumcarcinoom","short":"Het ovariumcarcinoom is kanker van de eierstok, vaak laat ontdekt doordat klachten vaag zijn.","definition":"<p>Het meest voorkomende type is het hooggradig sereus carcinoom. Klachten: opgeblazen gevoel, toename van de buikomvang (ascites), vroege verzadiging en plasklachten. Risicofactoren: BRCA1/2-mutaties, Lynch-syndroom, weinig zwangerschappen. Het CA-125 is vaak verhoogd. Behandeling met chirurgie en chemotherapie.</p>","image_url":"","wiki_title":"Ovarian cancer","match":"ovariumcarcinoom|eierstokkanker","option_only":true},"sinus frontalis":{"title":"Sinus frontalis","short":"De sinus frontalis is de bijholte in het voorhoofdsbeen, die via de ductus frontonasalis in de neus uitmondt.","definition":"<p>De <strong>voorhoofdsholte</strong> ontwikkelt zich pas in de kindertijd. Een infectie kan uitbreiden naar de oogkas of de voorste schedelgroeve (bijv. een abces of het Pott's puffy tumor), al is dat zeldzaam.</p>","image_url":"","wiki_title":"Frontal sinus","match":"sinus frontalis|voorhoofdsholte","option_only":true},"acute middenoorontsteking":{"title":"Otitis media acuta","short":"Otitis media acuta is een acute middenoorontsteking met oorpijn, koorts en een rood, bomberend trommelvlies.","definition":"<p><strong>Acute otitis media</strong> komt vooral bij jonge kinderen voor, vaak na een verkoudheid; verwekkers zijn virussen en bacteriën (pneumokok, <em>H. influenzae</em>, <em>Moraxella</em>). Een loopoor ontstaat bij perforatie van het trommelvlies. Meestal geneest het spontaan; pijnstilling is de basis, antibiotica alleen bij risicofactoren of ernstig beloop.</p>","image_url":"","wiki_title":"Otitis media","match":"acute middenoorontsteking","option_only":true},"chlamydia-infectie":{"title":"Chlamydia trachomatis","short":"Chlamydia trachomatis is een obligaat intracellulaire bacterie en de meest voorkomende bacteriële soa.","definition":"<p><strong>Chlamydia</strong> geeft vaak geen klachten; soms urethritis, cervicitis met afscheiding of bloedverlies na gemeenschap. Complicaties zijn salpingitis met subfertiliteit en extra-uteriene zwangerschap, epididymitis en reactieve artritis. Bij pasgeborenen conjunctivitis en pneumonie. Behandeling met doxycycline of azitromycine.</p>","image_url":"","wiki_title":"Chlamydia","match":"chlamydia-infectie","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"amoxycilline oraal":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline oraal","option_only":true},"n. laryngeus recurrens":{"title":"N. laryngeus recurrens","short":"De n. laryngeus recurrens is een tak van de n. vagus die vrijwel alle stembandspieren innerveert; links loopt hij om de aortaboog, rechts om de a. subclavia.","definition":"<p>Door zijn lange verloop is de <strong>n. laryngeus recurrens</strong> kwetsbaar bij schildklier-, slokdarm- en thoraxchirurgie en bij tumoren van long, slokdarm, schildklier en mediastinum, en (links) bij een aneurysma van de aortaboog. Uitval geeft heesheid door een stembandparese.</p>","image_url":"","wiki_title":"Recurrent laryngeal nerve","match":"n. laryngeus recurrens|nervus laryngeus recurrens","option_only":true},"xylometazoline":{"title":"Xylometazoline","short":"Xylometazoline is een α-agonist in neusspray die de neusslijmvliezen laat slinken en een verstopte neus snel opent.","definition":"<p>Bij gebruik van <strong>xylometazoline</strong> langer dan ongeveer een week ontstaat een rebound-zwelling van het slijmvlies, met een chronisch verstopte neus (rhinitis medicamentosa). Het wordt daarom kort gebruikt.</p>","image_url":"","wiki_title":"Xylometazoline","match":"xylometazoline|neusspray met xylometazoline|decongestivum","option_only":true},"medicamenteuze rhinitis":{"title":"Rhinitis medicamentosa","short":"Rhinitis medicamentosa is een chronisch verstopte neus door langdurig gebruik van decongestieve neusspray.","definition":"<p>Bij <strong>rhinitis medicamentosa</strong> leidt overmatig gebruik van α-agonisten zoals xylometazoline tot gewenning en rebound-zwelling. Behandeling: stoppen met de spray, eventueel tijdelijk ondersteund met een corticosteroïdneusspray.</p>","image_url":"","wiki_title":"Rhinitis medicamentosa","match":"medicamenteuze rhinitis|rhinitis medicamentosa","option_only":true},"koperspiraal":{"title":"Koperspiraal","short":"Een koperspiraal is een hormoonvrij voorbehoedsmiddel in de baarmoeder; koper werkt zaadceldodend en voorkomt innesteling.","definition":"<p>Het <strong>koperspiraal</strong> werkt 5–10 jaar en kan ook als noodanticonceptie tot 5 dagen na onbeschermde gemeenschap worden geplaatst. Bijwerkingen: hevigere en pijnlijkere menstruaties. Er is een klein risico op uitstoting en perforatie.</p>","image_url":"","wiki_title":"Copper IUD","match":"koperspiraal|koperhoudend iud|cu-iud","option_only":true},"progesteronspiraal":{"title":"Hormoonspiraal (levonorgestrel-IUS)","short":"De hormoonspiraal geeft lokaal levonorgestrel af, waardoor het cervixslijm taai wordt en het endometrium dun blijft.","definition":"<p>Het <strong>hormoonspiraal</strong> werkt 5–8 jaar, vermindert menstrueel bloedverlies (gebruikt bij menorragie) en beschermt het endometrium bij oestrogeensuppletie. Bijwerkingen in het begin zijn onregelmatig bloedverlies; daarna blijft de menstruatie vaak weg.</p>","image_url":"","wiki_title":"Hormonal intrauterine device","match":"progesteronspiraal|progesteron-spiraal|hormoonspiraal|mirena","option_only":true},"allergische conjunctivitis":{"title":"Allergische conjunctivitis","short":"Allergische conjunctivitis is een allergische ontsteking van het bindvlies, met jeukende, tranende en rode ogen aan beide kanten.","definition":"<p>De <strong>allergische conjunctivitis</strong> is vaak seizoensgebonden (pollen) of het hele jaar door (huisstofmijt, huisdieren), meestal samen met allergische rhinitis. Jeuk is het belangrijkste onderscheid met infectieuze conjunctivitis. Behandeling met antihistaminica of mestcelstabiliserende oogdruppels.</p>","image_url":"","wiki_title":"Allergic conjunctivitis","match":"allergische conjunctivitis|jeukende en tranende ogen|jeuk in de ogen","option_only":true},"brca1":{"title":"BRCA1 en BRCA2","short":"BRCA1 en BRCA2 zijn tumorsuppressorgenen voor DNA-herstel; mutaties geven een sterk verhoogd risico op borst- en eierstokkanker.","definition":"<p>Draagsters van een <strong>BRCA</strong>-mutatie hebben een levenslang risico op borstkanker van 60–70% en op ovariumcarcinoom van ongeveer 15–45%. Ook het risico op prostaat- en pancreaskanker is verhoogd (vooral BRCA2). Opties zijn intensieve screening en risicoreducerende operaties; PARP-remmers werken goed bij BRCA-gerelateerde tumoren.</p>","image_url":"","wiki_title":"BRCA mutation","match":"brca1|brca2|brca","option_only":true},"epistaxis":{"title":"Epistaxis (neusbloeding)","short":"Epistaxis is een neusbloeding, meestal uit de plexus van Kiesselbach vooraan in het neustussenschot.","definition":"<p>De meeste <strong>neusbloedingen</strong> zijn anterieur en stoppen met tien minuten stevig dichtknijpen van de neusvleugels, voorovergebogen zittend. Risicofactoren: neuspeuteren, droge lucht, antistolling, hypertensie en stollingsstoornissen. Posterieure bloedingen (ouderen) zijn ernstiger.</p>","image_url":"","wiki_title":"Nosebleed","match":"epistaxis|neusbloeding","option_only":true},"neuspoliep":{"title":"Neuspoliepen","short":"Neuspoliepen zijn goedaardige, druppelvormige zwellingen van het slijmvlies van neus en bijholten, met een verstopte neus en reukverlies.","definition":"<p><strong>Neuspoliepen</strong> horen bij chronische rhinosinusitis, vaak met astma en soms met overgevoeligheid voor aspirine (triade van Samter/Widal). Bij kinderen moet aan cystische fibrose worden gedacht. Behandeling met corticosteroïdneusspray, kortdurend orale steroïden of chirurgie.</p>","image_url":"","wiki_title":"Nasal polyp","match":"neuspoliep|neuspoliepen","option_only":true},"kieuwboogfistel":{"title":"Kieuwboogcyste of -fistel","short":"Een kieuwboogcyste of -fistel is een aangeboren restant van de kieuwbogen, meestal aan de voorrand van de m. sternocleidomastoideus.","definition":"<p>Een <strong>laterale halscyste</strong> (meestal van de tweede kieuwboog) kan pas bij een infectie opvallen als een gezwollen, pijnlijke zwelling in de hals. Een fistel kan een opening in de huid van de hals hebben. Behandeling is chirurgische verwijdering. Een mediane halscyste daarentegen ligt in de middellijn.</p>","image_url":"","wiki_title":"Branchial cleft cyst","match":"kieuwboogfistel|kieuwboogcyste|laterale halscyste","option_only":true},"atheroomcyste":{"title":"Epidermoïdcyste (atheroom)","short":"Een atheroomcyste is een goedaardige, met keratine gevulde cyste onder de huid, vaak met een zichtbaar centraal puntje.","definition":"<p>Een <strong>epidermoïdcyste</strong> komt voor op hoofd, hals en romp en kan ontsteken (rood, pijnlijk). Behandeling bij klachten is chirurgische verwijdering inclusief het kapsel, om terugkeer te voorkomen.</p>","image_url":"","wiki_title":"Epidermoid cyst","match":"atheroomcyste|atheroom|epidermoïdcyste","option_only":true},"moraxella catarrhalis":{"title":"Moraxella catarrhalis","short":"Moraxella catarrhalis is een gramnegatieve diplokok die otitis media, sinusitis en COPD-exacerbaties veroorzaakt.","definition":"<p><strong><em>M. catarrhalis</em></strong> maakt bijna altijd bètalactamase, waardoor amoxicilline alleen vaak niet werkt; amoxicilline-clavulaanzuur, macroliden of doxycycline wel.</p>","image_url":"","wiki_title":"Moraxella catarrhalis","match":"moraxella catarrhalis|moraxella","option_only":true},"sensorineuraal gehoorsverlies":{"title":"Perceptief gehoorverlies","short":"Bij perceptief (sensorineuraal) gehoorverlies is het binnenoor of de gehoorzenuw beschadigd.","definition":"<p>Oorzaken van <strong>perceptief gehoorverlies</strong> zijn ouderdom (presbyacusis), lawaai, ototoxische middelen, de ziekte van Ménière, een vestibulair schwannoom en congenitale infecties (CMV). Bij de test van Weber lateraliseert het geluid naar het goede oor, bij Rinne is luchtgeleiding beter dan beengeleiding. Plotseling perceptief verlies is een spoedgeval.</p>","image_url":"","wiki_title":"Sensorineural hearing loss","match":"sensorineuraal gehoorsverlies|perceptief gehoorverlies|sensorineuraal gehoorverlies|perceptieverlies","option_only":true},"contusio cerebri":{"title":"Contusio cerebri","short":"Een contusio cerebri is een kneuzing van het hersenweefsel door een trauma, vaak met kleine bloedingen en oedeem.","definition":"<p>Bij een <strong>hersenkneuzing</strong> ontstaan contusiehaarden vaak frontaal en temporaal, ook aan de tegenovergestelde kant van de klap (contrecoup). Er kan een langer bewustzijnsverlies en neurologische uitval zijn. Een commotio cerebri (hersenschudding) is functioneel zonder zichtbare afwijkingen.</p>","image_url":"","wiki_title":"Cerebral contusion","match":"contusio cerebri|hersenkneuzing","option_only":true},"tonsillectomie":{"title":"Tonsillectomie","short":"Bij een tonsillectomie worden de keelamandelen verwijderd, bijv. bij recidiverende tonsillitis, een peritonsillair abces of slaapapneu.","definition":"<p>Na een <strong>tonsillectomie</strong> is het belangrijkste risico een nabloeding, ook nog tot ongeveer tien dagen erna. Bij kinderen met obstructieve slaapapneu worden vaak ook de neusamandelen verwijderd.</p>","image_url":"","wiki_title":"Tonsillectomy","match":"tonsillectomie|amandelen knippen|adenotonsillectomie","option_only":true},"haemophilus influenza":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza","option_only":true},"sinus maxillaris":{"title":"Sinus maxillaris (kaakholte)","short":"De sinus maxillaris is de grootste bijholte, in het bovenkaakbeen; de afvoer ligt hoog, wat infecties bevordert.","definition":"<p>De bijholten zijn de <strong>sinus maxillaris</strong>, sinus frontalis, de zeefbeencellen (sinus ethmoidalis) en de sinus sphenoidalis. Ze monden uit in de neusholte. Wortels van de bovenste kiezen liggen vlak onder de kaakholte, waardoor tandinfecties een sinusitis kunnen geven.</p>","image_url":"","wiki_title":"Maxillary sinus","match":"sinus maxillaris|kaakholte|sinus ethmoidalis|sinus sfenoidalis","option_only":true},"ductus nasolacrimalis":{"title":"Ductus nasolacrimalis (traanbuis)","short":"De ductus nasolacrimalis voert traanvocht van de traanzak naar de onderste neusgang.","definition":"<p>Bij pasgeborenen is de <strong>traanbuis</strong> soms nog afgesloten, met een tranend oog en slijm, wat meestal vanzelf overgaat; anders volgt sondage. Bij volwassenen kan een afsluiting tot een ontsteking van de traanzak (dacryocystitis) leiden.</p>","image_url":"","wiki_title":"Nasolacrimal duct","match":"ductus nasolacrimalis|traanbuis|traanwegen","option_only":true},"tuba eustachii":{"title":"Buis van Eustachius","short":"De buis van Eustachius verbindt het middenoor met de neuskeelholte en zorgt voor drukvereffening en afvoer van vocht.","definition":"<p>Bij jonge kinderen is de <strong>buis van Eustachius</strong> korter en horizontaler, waardoor middenoorontstekingen vaker voorkomen. Een slecht werkende buis geeft otitis media met effusie. Bij volwassenen met eenzijdig aanhoudend vocht achter het trommelvlies moet een nasofarynxtumor worden uitgesloten.</p>","image_url":"","wiki_title":"Eustachian tube","match":"tuba eustachii|buis van eustachius|tuba auditiva","option_only":true},"acuut rheuma (rheumatic fever)":{"title":"Acuut reuma","short":"Acuut reuma is een ontstekingsziekte enkele weken na een keelinfectie met groep A-streptokokken, door kruisreactie van antistoffen.","definition":"<p><strong>Acuut reuma</strong> geeft volgens de Jones-criteria o.a. carditis, een migrerende polyartritis, chorea van Sydenham, erythema marginatum en subcutane noduli. De carditis kan leiden tot chronische reumatische klepziekte, vooral van de mitralisklep. Het is in Nederland zeldzaam geworden, maar wereldwijd nog een belangrijke oorzaak van hartziekte.</p>","image_url":"","wiki_title":"Rheumatic fever","match":"acuut rheuma (rheumatic fever)","option_only":true},"nervus laryngeus recurrens":{"title":"N. laryngeus recurrens","short":"De n. laryngeus recurrens is een tak van de n. vagus die vrijwel alle stembandspieren innerveert; links loopt hij om de aortaboog, rechts om de a. subclavia.","definition":"<p>Door zijn lange verloop is de <strong>n. laryngeus recurrens</strong> kwetsbaar bij schildklier-, slokdarm- en thoraxchirurgie en bij tumoren van long, slokdarm, schildklier en mediastinum, en (links) bij een aneurysma van de aortaboog. Uitval geeft heesheid door een stembandparese.</p>","image_url":"","wiki_title":"Recurrent laryngeal nerve","match":"nervus laryngeus recurrens","option_only":true},"nullipariteit":{"title":"Nullipariteit","short":"Het nooit een kind gebaard hebben. Risicofactor voor onder meer ovarium- en endometriumcarcinoom.","definition":"<p><b>Nullipariteit</b> verhoogt het aantal ovulatiecycli en daarmee bepaalde gynaecologische kankerrisico’s.</p>","image_url":"","wiki_title":"Gravidity and parity","match":"nullipariteit","option_only":true},"bellse parese":{"title":"Bellse parese","short":"Idiopathische perifere aangezichtsverlamming; diagnose per exclusionem van andere oorzaken van facialisparese.","definition":"<p>Een <b>Bellse parese</b> is een acute, <b>idiopathische</b> perifere verlamming van de nervus facialis (aangezichtszenuw). Het is een uitsluitingsdiagnose: andere oorzaken zoals herpes zoster (Ramsay Hunt), CVA, borreliose en tumoren moeten zijn uitgesloten.</p>","image_url":"","wiki_title":"Bell's palsy","match":"bellse parese","option_only":true},"dose-response relation":{"title":"Criteria van Bradford Hill","short":"De criteria van Bradford Hill helpen te beoordelen of een gevonden verband oorzakelijk is.","definition":"<p>De criteria zijn o.a. sterkte van het verband, consistentie, specificiteit, tijdsvolgorde (oorzaak vóór gevolg, het enige noodzakelijke criterium), <strong>dosis-responsrelatie</strong>, biologische plausibiliteit, samenhang met bestaande kennis, experimenteel bewijs (reversibiliteit) en analogie.</p>","image_url":"","wiki_title":"Bradford Hill criteria","match":"dose-response relation|reversibility|specificity|biologic plausibility|bradford hill","option_only":true},"reversibility":{"title":"Criteria van Bradford Hill","short":"De criteria van Bradford Hill helpen te beoordelen of een gevonden verband oorzakelijk is.","definition":"<p>De criteria zijn o.a. sterkte van het verband, consistentie, specificiteit, tijdsvolgorde (oorzaak vóór gevolg, het enige noodzakelijke criterium), <strong>dosis-responsrelatie</strong>, biologische plausibiliteit, samenhang met bestaande kennis, experimenteel bewijs (reversibiliteit) en analogie.</p>","image_url":"","wiki_title":"Bradford Hill criteria","match":"reversibility","option_only":true},"specificity":{"title":"Criteria van Bradford Hill","short":"De criteria van Bradford Hill helpen te beoordelen of een gevonden verband oorzakelijk is.","definition":"<p>De criteria zijn o.a. sterkte van het verband, consistentie, specificiteit, tijdsvolgorde (oorzaak vóór gevolg, het enige noodzakelijke criterium), <strong>dosis-responsrelatie</strong>, biologische plausibiliteit, samenhang met bestaande kennis, experimenteel bewijs (reversibiliteit) en analogie.</p>","image_url":"","wiki_title":"Bradford Hill criteria","match":"specificity","option_only":true},"biologic plausibility":{"title":"Criteria van Bradford Hill","short":"De criteria van Bradford Hill helpen te beoordelen of een gevonden verband oorzakelijk is.","definition":"<p>De criteria zijn o.a. sterkte van het verband, consistentie, specificiteit, tijdsvolgorde (oorzaak vóór gevolg, het enige noodzakelijke criterium), <strong>dosis-responsrelatie</strong>, biologische plausibiliteit, samenhang met bestaande kennis, experimenteel bewijs (reversibiliteit) en analogie.</p>","image_url":"","wiki_title":"Bradford Hill criteria","match":"biologic plausibility","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true}};
